import React, { useState, useEffect } from 'react';
import { Check, Plus, Search, ArrowUpDown, Edit, Trash2 } from 'lucide-react';

// Colors from the poster
const colors = {
  primary: '#f7abff',     // Pink background
  secondary: '#2f2a2f',   // Dark gray/black
  accent: '#3CDFFF',      // Cyan blue accent
  darkAccent: '#620f87',  // Deep purple
  light: '#f9f9f9',       // White text
  midGray: '#797979',     // Mid gray
  successGreen: '#4ADE80',
  warningOrange: '#F97316',
  errorRed: '#EF4444'
};

const TasksPage = ({ tasks, milestones, onAddTask, onUpdateTask, onDeleteTask }) => {
  // State for filtering and sorting
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState({ field: 'id', direction: 'asc' });

  // State for new task form visibility for each column
  const [showAddTaskFormForMilestone, setShowAddTaskFormForMilestone] = useState({});
  const [newTask, setNewTask] = useState({
    name: '',
    milestone: '',
    completed: false
  });

  // State for edit task
  const [editingTask, setEditingTask] = useState(null);

  // Handle input change for the new task form
  const handleNewTaskInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setNewTask({
      ...newTask,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  // Handle adding a new task to a specific milestone
  const handleAddTaskToMilestone = (milestoneName) => {
    setNewTask({ ...newTask, milestone: milestoneName });
    setShowAddTaskFormForMilestone(prev => ({ ...prev, [milestoneName]: true }));
  };

  // Handle closing the add task form for a specific milestone
  const handleCloseAddTaskForm = (milestoneName) => {
    setShowAddTaskFormForMilestone(prev => ({ ...prev, [milestoneName]: false }));
    setNewTask({ name: '', milestone: '', completed: false });
  };

  // Handle submitting the new task
  const handleSubmitNewTask = (e) => {
    e.preventDefault();
    onAddTask(newTask);
    setNewTask({ name: '', milestone: '', completed: false });
    setShowAddTaskFormForMilestone({}); // Close all forms after submission
  };

  // Handle edit input changes
  const handleEditInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setEditingTask({
      ...editingTask,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  // Handle edit form submission
  const handleEditSubmit = (e) => {
    e.preventDefault();
    onUpdateTask(editingTask.id, editingTask);
    setEditingTask(null);
  };

  // Handle sorting
  const handleSort = (field) => {
    setSortBy(prev => ({
      field,
      direction: prev.field === field && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  // Filter tasks by search term
  const searchedTasks = tasks.filter(task =>
    task.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="rounded-lg p-4" style={{ backgroundColor: colors.secondary }}>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-xl font-bold text-white mb-2">Tasks</h2>
          <p className="text-gray-400">Manage and track production tasks across milestones</p>
        </div>
      </div>

      {/* Search Filter */}
      <div className="relative mb-6">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-gray-400" />
        </div>
        <input
          type="text"
          placeholder="Search tasks..."
          className="bg-gray-800 text-white pl-10 pr-4 py-2 rounded w-full border border-gray-700"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Milestone Columns */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {milestones.map(milestone => (
          <div key={milestone.id} className="bg-gray-900 rounded-lg p-4">
            <div className="flex justify-between items-center mb-2">
              <h3 className="text-lg font-semibold text-white">{milestone.name}</h3>
              <button
                className="p-1 rounded-full hover:bg-gray-800"
                onClick={() => handleAddTaskToMilestone(milestone.name)}
              >
                <Plus className="h-4 w-4 text-white" />
              </button>
            </div>

            {/* Add Task Form for this milestone */}
            {showAddTaskFormForMilestone[milestone.name] && (
              <form onSubmit={handleSubmitNewTask} className="mb-4">
                <input
                  type="text"
                  name="name"
                  value={newTask.name}
                  onChange={handleNewTaskInputChange}
                  placeholder="Task name"
                  className="w-full bg-gray-800 border border-gray-700 rounded px-2 py-1 text-white mb-2"
                  required
                />
                <div className="flex items-center mb-2">
                  <input
                    type="checkbox"
                    name="completed"
                    id={`completed-${milestone.id}`}
                    checked={newTask.completed}
                    onChange={handleNewTaskInputChange}
                    className="h-4 w-4 mr-2"
                  />
                  <label htmlFor={`completed-${milestone.id}`} className="text-gray-400">Completed</label>
                </div>
                <div className="flex justify-end">
                  <button
                    type="button"
                    onClick={() => handleCloseAddTaskForm(milestone.name)}
                    className="px-3 py-1 rounded border border-gray-700 text-gray-400 mr-2"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-3 py-1 rounded text-white"
                    style={{ backgroundColor: colors.accent }}
                  >
                    Add
                  </button>
                </div>
              </form>
            )}

            {/* Tasks in this milestone */}
            {searchedTasks
              .filter(task => task.milestone === milestone.name)
              .sort((a, b) => {
                const direction = sortBy.direction === 'asc' ? 1 : -1;
                if (sortBy.field === 'name') {
                  return direction * a.name.localeCompare(b.name);
                }
                return direction * (a.id - b.id);
              })
              .map(task => (
                <div key={task.id} className="bg-gray-800 rounded-md p-2 mb-2 flex items-center justify-between">
                  <div className="flex items-center">
                    <div
                      className="cursor-pointer mr-2"
                      onClick={() => onUpdateTask(task.id, { ...task, completed: !task.completed })}
                    >
                      {task.completed ? (
                        <div className="h-5 w-5 rounded-full bg-green-500 flex items-center justify-center">
                          <Check className="h-3 w-3 text-white" />
                        </div>
                      ) : (
                        <div className="h-5 w-5 rounded-full border border-gray-500" />
                      )}
                    </div>
                    <span className={`text-white ${task.completed ? 'line-through text-gray-400' : ''}`}>{task.name}</span>
                  </div>
                  <div className="flex space-x-2">
                    <button
                      className="p-1 rounded hover:bg-gray-700"
                      onClick={() => setEditingTask(task)}
                    >
                      <Edit className="h-4 w-4 text-gray-400" />
                    </button>
                    <button
                      className="p-1 rounded hover:bg-red-900"
                      onClick={() => onDeleteTask(task.id)}
                    >
                      <Trash2 className="h-4 w-4 text-gray-400" />
                    </button>
                  </div>
                </div>
              ))}
            {searchedTasks.filter(task => task.milestone === milestone.name).length === 0 && (
              <p className="text-gray-500 text-sm">No tasks in this milestone.</p>
            )}
          </div>
        ))}
      </div>

      {/* Edit Task Modal */}
      {editingTask && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-gray-900 rounded-lg p-6 max-w-md w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-white">Edit Task</h3>
              <button
                className="text-gray-400 hover:text-white"
                onClick={() => setEditingTask(null)}
              >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="h-5 w-5">
                  <path fillRule="evenodd" d="M5.47 5.47a.75.75 0 011.06 0L12 10.94l5.47-5.47a.75.75 0 111.06 1.06L13.06 12l5.47 5.47a.75.75 0 11-1.06 1.06L12 13.06l-5.47 5.47a.75.75 0 01-1.06-1.06L10.94 12 5.47 6.53a.75.75 0 010-1.06z" clipRule="evenodd" />
                </svg>
              </button>
            </div>

            <form onSubmit={handleEditSubmit}>
              <div className="space-y-4">
                <div>
                  <label className="block text-gray-400 mb-1">Task Name</label>
                  <input
                    type="text"
                    name="name"
                    value={editingTask.name}
                    onChange={handleEditInputChange}
                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                    required
                  />
                </div>

                <div>
                  <label className="block text-gray-400 mb-1">Milestone</label>
                  <select
                    name="milestone"
                    value={editingTask.milestone}
                    onChange={handleEditInputChange}
                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                    required
                    disabled // Prevent changing milestone during edit for simplicity
                  >
                    {milestones.map(milestone => (
                      <option key={milestone.id} value={milestone.name}>{milestone.name}</option>
                    ))}
                  </select>
                </div>

                <div className="flex items-center">
                  <input
                    type="checkbox"
                    name="completed"
                    id="editCompleted"
                    checked={editingTask.completed}
                    onChange={handleEditInputChange}
                    className="h-4 w-4 mr-2"
                  />
                  <label htmlFor="editCompleted" className="text-white">Mark as completed</label>
                </div>

                <div className="flex justify-end">
                  <button
                    type="button"
                    onClick={() => setEditingTask(null)}
                    className="px-4 py-2 rounded border border-gray-700 text-gray-400 mr-2"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-4 py-2 rounded text-white"
                    style={{ backgroundColor: colors.accent }}
                  >
                    Save Changes
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TasksPage;
